package com.spai.portal.web;import java.util.*;import com.spai.portal.common.ApiResponse;import com.spai.portal.task.domain.*;import com.spai.portal.task.repository.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/dashboard")public class DashboardController{private final DeliveryTaskRepository tasks;private final TaskProgressRepository progress;public DashboardController(DeliveryTaskRepository tasks,TaskProgressRepository progress){this.tasks=tasks;this.progress=progress;}@GetMapping("/statistics")public ApiResponse<Map<String,Object>>statistics(){List<DeliveryTask>all=tasks.findAll();List<TaskProgress>ps=progress.findAll();Map<String,Object>m=new LinkedHashMap<String,Object>();m.put("total",all.size());m.put("highPriority",all.stream().filter(t->"高".equals(t.getPriority())).count());m.put("highDifficulty",all.stream().filter(t->"高".equals(t.getDifficulty())).count());m.put("completed",ps.stream().filter(p->"已完成".equals(p.getStatus())).count());return ApiResponse.ok(m);}}
